mapper.select:
SELECT
  count(*) totcnt
FROM
  ttokssaemdb.vocamemo


    AND memberid = #{memberid}


    AND memodate = #{memodate}

mapper.update:
UPDATE ttokssaemdb.checkvocaplan
SET
  examflag = 'B'
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}

UPDATE ttokssaemdb.checkvocaplan
SET
  examflag = #{finishflag}
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}

UPDATE ttokssaemdb.vocaexam
SET
  result = #{finishflag},
  total = #{total},
  wrong = #{wrong},
  findate = now()
WHERE
  memberid = #{memberid}
  AND memodate = #{memodate}
  AND degree = #{degree}

UPDATE ttokssaemdb.vocasolve
SET
  answer = #{answer},
  result = #{result}
WHERE
  id = #{id}

mapper.select:
SELECT
  count(*) totcnt
FROM
  ttokssaemdb.vocasolve vocasolve

  AND vocasolve.memberid = #{memberid}
  AND vocasolve.memodate = #{memodate}
  AND vocasolve.degree = #{degree}

SELECT vocasolve.id, vocasolve.memberid, vocasolve.memodate, vocasolve.degree, vocasolve.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocasolve.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocasolve.vocano, vocasolve.word, voca.answer voca_answer, vocasolve.answer, vocasolve.result FROM ttokssaemdb.vocasolve vocasolve, ttokssaemdb.voca voca
AND voca.vocalevel = vocasolve.vocalevel AND voca.vocano = vocasolve.vocano AND vocasolve.memberid = #{memberid} AND vocasolve.memodate = #{memodate} AND vocasolve.degree = #{degree}
ORDER BY vocano
LIMIT ${length} OFFSET ${start}

SELECT count(*) totcnt FROM ttokssaemdb.member member, ttokssaemdb.checkvocaplan vocatest
AND member.memberid = vocatest.memberid
AND vocatest.memberid = #{targetid}
AND vocatest.memberid = #{memberid}

SELECT member.memberid, member.membername, vocatest.id, vocatest.memodate, vocatest.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocatest.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocatest.vocano, vocatest.targetcount, vocatest.lastyn, vocatest.examflag, IFNULL((SELECT MAX(ve.degree) FROM ttokssaemdb.vocaexam ve WHERE ve.memberid = vocatest.memberid AND ve.memodate = vocatest.memodate), 0) degree, IFNULL((SELECT total FROM ttokssaemdb.vocaexam WHERE memodate = vocatest.memodate AND memberid = vocatest.memberid ORDER BY degree DESC LIMIT 1), 0) total, IFNULL((SELECT wrong FROM ttokssaemdb.vocaexam WHERE memodate = vocatest.memodate AND memberid = vocatest.memberid ORDER BY degree DESC LIMIT 1), 0) wrong FROM ttokssaemdb.member member, ttokssaemdb.checkvocaplan vocatest
AND member.memberid = vocatest.memberid
AND vocatest.memberid = #{targetid}
AND vocatest.memberid = #{memberid}
ORDER BY id desc
LIMIT ${length} OFFSET ${start}
